mapper.select:
SELECT 
    a.id,
    a.acceptance_id AS acceptanceId,
    a.acceptance_no AS acceptanceNo,
    a.purchase_id AS purchaseId,
    a.warehouse_id AS warehouseId,
    a.acceptance_date AS acceptanceDate,
    a.acceptance_by AS acceptanceBy,
    a.acceptance_status AS acceptanceStatus,
    a.total_amount AS totalAmount,
    a.remark,
    a.create_by AS createBy,
    a.create_time AS createTime
FROM spd_acceptance a
WHERE a.del_flag = #{delFlag}

    AND a.acceptance_no LIKE CONCAT('%', #{query.acceptanceNo}, '%')


    AND a.purchase_id = #{query.purchaseId}


    AND a.warehouse_id = #{query.warehouseId}


    AND a.acceptance_status = #{query.acceptanceStatus}


    AND a.acceptance_by = #{query.acceptanceBy}


    AND a.acceptance_date >= #{query.startDate}


    AND a.acceptance_date <= #{query.endDate}

ORDER BY a.create_time DESC
